static void pump(DWORD ms){ULONGLONG end=GetTickCount64()+ms;MSG m;do{unsigned n=0;while(n++<3000&&PeekMessageW(&m,NULL,0,0,PM_REMOVE)){if(m.message!=WM_QUIT){TranslateMessage(&m);DispatchMessageW(&m);++dispatched;}}if(GetTickCount64()<end)MsgWaitForMultipleObjects(0,NULL,FALSE,1,QS_ALLINPUT);}while(GetTickCount64()<end);}
