static void result(ui_status_t status,const char *json,void *data){(void)data;script_status=status;snprintf(reply,sizeof(reply),"%s",json?json:"null");done=1;}
static int script(ui_web_view_t *v,const char *js){ULONGLONG start=GetTickCount64();do{done=0;check(ui_webview2_view_execute_script(v,js,result,NULL)==UI_STATUS_OK,"execute observation script");while(!done&&GetTickCount64()-start<5000)pump(1);if(done&&script_status==UI_STATUS_CANCELLED)printf("OBSERVATION_CANCELLED tick=%llu (presentation epoch changed; retry within original 5s gate)\n",GetTickCount64());else break;}while(GetTickCount64()-start<5000);check(done&&script_status==UI_STATUS_OK,"observation callback completes");return done&&script_status==UI_STATUS_OK;}
static int ready(ui_web_view_t *v){ULONGLONG start=GetTickCount64();int r=0,n=0;do{ui_webview2_view_get_state(v,&r,&n);if(r&&n)return 1;pump(1);}while(GetTickCount64()-start<15000);check(0,"Runtime ready/navigation");return 0;}
