static int input_allowed(void){DWORD pid=0;HDESK desktop=OpenInputDesktop(0,FALSE,DESKTOP_READOBJECTS);GetWindowThreadProcessId(GetForegroundWindow(),&pid);if(desktop)CloseDesktop(desktop);if(pid!=GetCurrentProcessId()||!desktop){check(0,"unlocked foreground belongs to probe; stop input");return 0;}return 1;}
