static void observe(ui_web_view_t *v){if(!observer)return;script(v,"window.__p6events=[];['keydown','keyup'].forEach(function(type){document.addEventListener(type,function(ev){var e=ev.target;function record(when){window.__p6events.push({type:type,when:when,key:ev.key,code:ev.code,ctrl:ev.ctrlKey,shift:ev.shiftKey,alt:ev.altKey,target:e.id,active:document.activeElement.id,start:e.selectionStart,end:e.selectionEnd,top:e.scrollTop,left:e.scrollLeft,prevented:ev.defaultPrevented});}record('capture');requestAnimationFrame(function(){record('after-default')});},true)});true");}
static void original(ui_web_view_t *v,const char *prefix){char phase[100];snprintf(phase,sizeof(phase),"%s-original-CtrlHome",prefix);key(v,VK_HOME,1,phase,1);for(int i=0;i<19;++i){snprintf(phase,sizeof(phase),"%s-original-Down-%02d",prefix,i+1);key(v,VK_DOWN,0,phase,i==0||i==18);}snprintf(phase,sizeof(phase),"%s-original-Home",prefix);key(v,VK_HOME,0,phase,1);snprintf(phase,sizeof(phase),"%s-original-End",prefix);key(v,VK_END,0,phase,1);}
